// seq_detector_jk.sv - composite detector: Z1 = 101 always; Z2 = 011 until it fires, then only Z1 until Z1 fires.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: JK, logic: minimal POS (exact two-level minimisation with don't-cares),
// next-state 7 two-input gates, outputs 5 two-input gates.
// State encoding:
//   S0     = 000
//   T0/T1  = 111
//   S1     = 011
//   S2     = 001
//   T2/T3  = 100
//   S3     = 101
//   S4     = 010
//   T4     = 110
// 8 states after minimising the 10-state composite machine; encoding chosen by prioritized adjacency
// plus an exhaustive search over all 8! encodings (scripts/explore_detector.py).

module seq_detector_jk (
  input  logic clk,
  input  logic rst,   // synchronous, to S0
  input  logic x,
  output logic z1,
  output logic z2
);
  logic [2:0] q, qn;
  logic j0, j1, j2, k0, k1, k2;
  assign j2     = q[1] & x;  // 1 gates
  assign k2     = q[0] & ~x & qn[1];  // 2 gates
  assign j1     = ~x;  // 0 gates
  assign k1     = x;  // 0 gates
  assign j0     = (qn[2] | q[1]);  // 1 gates
  assign k0     = (q[2] | ~x) & (qn[1] | x);  // 3 gates
  assign z1     = q[1] & x & qn[0];  // 2 gates
  assign z2     = q[2] & q[0] & x & qn[1];  // 3 gates

  jk_ff u_q2 (.clk, .j(j2 & ~rst), .k(k2 | rst), .q(q[2]), .qn(qn[2]));
  jk_ff u_q1 (.clk, .j(j1 & ~rst), .k(k1 | rst), .q(q[1]), .qn(qn[1]));
  jk_ff u_q0 (.clk, .j(j0 & ~rst), .k(k0 | rst), .q(q[0]), .qn(qn[0]));
endmodule
